BEGIN;
CREATE TEMP TABLE assertion_count(n int);INSERT INTO assertion_count VALUES(0);
CREATE FUNCTION pg_temp.check_it(v boolean,label text)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'Assertion failed: %',label;END IF;UPDATE assertion_count SET n=n+1;END$$;
CREATE FUNCTION pg_temp.intake()RETURNS jsonb LANGUAGE sql AS $$SELECT '{"version":1,"subjectKind":"real_estate_development","scope":"development","sector":"residential","transaction":"for_sale","lifecycle":"prelaunch","offeringKind":"home_plan","primaryIntent":"register_interest","country":"Canada","timezone":"America/Vancouver","canonicalName":"Reviewed identity","aliases":"Other name","ownershipEntity":"Owner","managementCompany":"Manager","market":"Metro","submarket":"District","products":["website"],"setupOwner":"Setup owner","launchTarget":"2027-01-01","successMetric":"Qualified inquiries","successTarget":"Review baseline","publicContact":{"name":"Sales","phone":"+1 555 0100","email":"public@example.test","confirmed":true},"tourUrl":"https://example.test/tour","applicationUrl":"","officeHours":"Weekdays 9–5","brandMode":"existing","brandVoice":"Clear","audience":"Supplied audience","legalEntity":"Legal entity","jurisdiction":"BC","reviewer":"Legal reviewer","sources":[{"id":"aa570000-0000-4000-8000-000000000001","kind":"google_drive","label":"Authoritative folder","reference":"https://drive.google.com/drive/folders/example","provider":"Google Drive","externalId":"property-reference","owner":"Source owner","observedAt":"2026-10-30","reviewAfter":"2026-11-30","visibility":"internal","notes":"Review monthly"}]}'::jsonb$$;
CREATE FUNCTION pg_temp.profile()RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('name','Onboarding intake SQL fixture','propertyType',null,'address','{"street":"1 Street","city":"City","state":"BC","zip":"V0A"}'::jsonb,'websiteUrl','','additionalUrls','[]'::jsonb,'unitCount',0,'yearBuilt',null,'amenities','[]'::jsonb,'specialFeatures','[]'::jsonb,'brandVoice','Clear','targetAudience','Supplied audience','intake',pg_temp.intake())$$;
DO $$DECLARE actor uuid:='11111111-1111-1111-1111-111111111111';pid uuid:=gen_random_uuid();other uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();r jsonb;s jsonb;b jsonb;h text;old_hash text;profile jsonb;row_profile jsonb;reviewed_id uuid:=gen_random_uuid();
BEGIN
 PERFORM pg_temp.check_it(to_regprocedure('public.brain_can(uuid,uuid,text)') IS NOT NULL,'current access schema exists');
 PERFORM pg_temp.check_it(to_regprocedure('public.property_onboarding_draft(uuid,uuid,jsonb)') IS NOT NULL,'draft schema exists');
 r:=public.create_property_from_setup(pid,actor,jsonb_build_object('profile',pg_temp.profile(),'template',null));
 PERFORM pg_temp.check_it(r->>'state'='created','expanded property created atomically');
 PERFORM pg_temp.check_it(public.brain_can(actor,pid,'manage'),'creator has current explicit access');
 s:=public.property_edit_snapshot(pid);h:=public.knowledge_hash(s);s:=s-'contextCity';
 PERFORM pg_temp.check_it(s->'profile'->'intake'=pg_temp.intake(),'all intake values retained in canonical property history');
 PERFORM pg_temp.check_it((SELECT address->>'country'='Canada' AND settings->>'timezone'='America/Vancouver' AND settings->'publicContact'->>'email'='public@example.test' FROM public.properties WHERE id=pid),'country timezone and public contact project to their consumers');
 SELECT v.profile INTO row_profile FROM public.property_vertical_profile_versions v JOIN public.properties p ON p.current_vertical_profile_version_id=v.id WHERE p.id=pid;
 PERFORM pg_temp.check_it(row_profile->'attributes'->'siteforgeComposition'->>'archetype'='for_sale_community','for-sale model does not fall back to apartments');
 PERFORM pg_temp.check_it((SELECT count(*)=9 FROM public.onboarding_tasks WHERE property_id=pid),'website selects applicable identity source brand inventory legal and readiness tasks');
 PERFORM pg_temp.check_it(NOT EXISTS(SELECT 1 FROM public.onboarding_tasks WHERE property_id=pid AND metadata->>'setupKey' LIKE 'connection_%'),'no ad or provider task is invented');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor)->>'revision'='0','new private draft starts at revision zero');
 b:=jsonb_build_object('requestId',rid,'expectedRevision',0,'baseHash',h,'draft',s||'{"step":"contacts"}');
 r:=public.property_onboarding_draft(pid,actor,b);
 PERFORM pg_temp.check_it(r->>'state'='saved' AND r->>'revision'='1','private draft saves');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor,b)=r,'exact lost-response retry returns its original receipt');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor,b||jsonb_build_object('draft',s||'{"step":"review"}'))->>'state'='conflict','same request cannot change content');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor,b||jsonb_build_object('requestId',gen_random_uuid()))->>'state'='changed','stale revision cannot overwrite a draft');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,gen_random_uuid())->>'state'='forbidden','foreign actor cannot read a private draft');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor)->'draft'=s||'{"step":"contacts"}'::jsonb,'reload returns every saved field and step');
 PERFORM pg_temp.check_it(public.knowledge_hash(public.property_edit_snapshot(pid))=h,'saving an unfinished draft does not mutate reviewed property data');
 r:=public.create_property_from_setup(other,actor,jsonb_build_object('profile',pg_temp.profile()-'intake','template',null));
 PERFORM pg_temp.check_it(NOT(public.property_edit_snapshot(other)->'profile'?'intake'),'legacy snapshot shape is unchanged');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(other,actor,b)->>'state'='conflict','receipt cannot cross properties');
 -- Simulate a newer independent review before changing only setup ownership/products.
 INSERT INTO public.property_vertical_profile_versions(id,org_id,property_id,version,subject_kind,vertical_key,mapping_status,mapping_reason,vertical_pack_key,vertical_pack_version,vertical_pack_content_hash,profile,content_hash)
 SELECT reviewed_id,v.org_id,v.property_id,v.version+1,v.subject_kind,v.vertical_key,'confirmed','Independent reviewed classification',v.vertical_pack_key,v.vertical_pack_version,v.vertical_pack_content_hash,jsonb_set(v.profile,'{attributes,reviewedSeparately}','true'),public.knowledge_hash(jsonb_set(v.profile,'{attributes,reviewedSeparately}','true'))
 FROM public.property_vertical_profile_versions v JOIN public.properties p ON p.current_vertical_profile_version_id=v.id WHERE p.id=pid;
 UPDATE public.properties SET current_vertical_profile_version_id=reviewed_id WHERE id=pid;
 profile:=s->'profile';profile:=jsonb_set(profile,'{intake,products}','[]');profile:=jsonb_set(profile,'{intake,setupOwner}','"New setup owner"');
 r:=public.save_property_setup(gen_random_uuid(),pid,actor,s||jsonb_build_object('profile',profile,'connectionRequests','[{"platform":"google_ads","accountId":"","accountName":"","notes":""},{"platform":"pms","accountId":"","accountName":"","notes":""}]'::jsonb,'expectedHash',h,'reason','Review changed product intent'));
 PERFORM pg_temp.check_it(r->>'state'='saved','product changes save');
 PERFORM pg_temp.check_it((SELECT current_vertical_profile_version_id=reviewed_id FROM public.properties WHERE id=pid),'unrelated setup edits preserve an independently reviewed classification');
 PERFORM pg_temp.check_it((SELECT metadata->>'href'='/dashboard/community?section=overview&setupPanel=advertising#community-settings' FROM public.onboarding_tasks WHERE property_id=pid AND metadata->>'setupKey'='connection_google_ads'),'advertising task opens the current connection panel');
 PERFORM pg_temp.check_it((SELECT metadata->>'href'='/dashboard/floor-plans' FROM public.onboarding_tasks WHERE property_id=pid AND metadata->>'setupKey'='connection_pms'),'inventory source task opens inventory review rather than ad imports');
 PERFORM pg_temp.check_it((SELECT count(*)=4 FROM public.onboarding_task_workspaces w JOIN public.onboarding_tasks t ON t.id=w.task_id WHERE t.property_id=pid AND w.archived),'no-longer-applicable pending tasks are archived');
 PERFORM pg_temp.check_it((SELECT bool_and(metadata->>'owner'='New setup owner') FROM public.onboarding_tasks t JOIN public.onboarding_task_workspaces w ON w.task_id=t.id WHERE t.property_id=pid AND NOT w.archived),'task responsibilities refresh with history');
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor,b||jsonb_build_object('requestId',gen_random_uuid(),'expectedRevision',1))->>'state'='property_changed','canonical edits block an old draft base');
 old_hash:=h;s:=public.property_edit_snapshot(pid);h:=public.knowledge_hash(s);s:=s-'contextCity';
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor,b||jsonb_build_object('requestId',gen_random_uuid(),'expectedRevision',1,'baseHash',h,'draft',s||'{"step":"review"}'))->>'state'='saved','explicit reload can save against latest canonical property');
 profile:=s->'profile';profile:=jsonb_set(profile,'{intake,sector}','"commercial"');
 r:=public.save_property_setup(gen_random_uuid(),pid,actor,s||jsonb_build_object('profile',profile,'expectedHash',h,'reason','Retain an unresolved classification draft'));
 PERFORM pg_temp.check_it(r->>'state'='saved','unresolved classification can be retained');
 PERFORM pg_temp.check_it((SELECT v.mapping_status='needs_review' AND NOT(v.profile->'attributes'?'siteforgeComposition') FROM public.properties p JOIN public.property_vertical_profile_versions v ON v.id=p.current_vertical_profile_version_id WHERE p.id=pid),'incompatible classification cannot masquerade as confirmed');
 PERFORM pg_temp.check_it(NOT EXISTS(SELECT 1 FROM public.integration_credentials WHERE property_id=pid) AND NOT EXISTS(SELECT 1 FROM public.knowledge_materials WHERE property_id=pid),'setup never connects credentials or publishes knowledge');
 PERFORM pg_temp.check_it(NOT has_table_privilege('authenticated','public.property_onboarding_drafts','SELECT') AND NOT has_function_privilege('authenticated','public.property_onboarding_draft(uuid,uuid,jsonb)','EXECUTE'),'direct client roles cannot bypass actor-bound draft API');
 PERFORM pg_temp.check_it((SELECT relrowsecurity FROM pg_class WHERE oid='public.property_onboarding_drafts'::regclass),'draft table has row level security');
 UPDATE public.community_access_grants SET revoked_at=clock_timestamp() WHERE actor_id=actor AND property_id=pid;
 PERFORM pg_temp.check_it(public.property_onboarding_draft(pid,actor)->>'state'='forbidden','revoked access blocks even an existing private draft');
 PERFORM pg_temp.check_it(public.save_property_setup(gen_random_uuid(),pid,actor,'{}')->>'state'='forbidden','existing public property save wrapper still enforces current community access');
END$$;
SELECT 'onboarding intake assertions passed: '||n FROM assertion_count;
ROLLBACK;
